INSERT INTO `episodios` VALUES (1,1,'Piloto',58,9.0,1,'Un profesor de química recibe un diagnóstico terminal y decide convertirse en fabricante de metanfetaminas.','2008-01-20'),(2,1,'Gato en un saco',47,8.7,2,'Walt y Jesse tratan de deshacerse de dos cuerpos mientras que al mismo tiempo tienen que lidiar con un testigo problemático.','2009-05-10'),(3,1,'Mandala',48,8.6,2,'Walt y Jesse deciden buscar un nuevo socio para poder expandir su negocio.','2009-05-17'),(4,1,'Phoenix',47,9.1,2,'Walt experimenta uno de sus mayores conflictos éticos cuando Jesse hace una nueva amiga.','2009-05-24'),(5,1,'ABQ',47,9.2,2,'Desastres colaterales llevan a Walt a manipular eventos que afectan a los que lo rodean.','2009-05-31'),(6,1,'No más',47,9.0,3,'Walt lidia con las consecuencias de sus acciones. Jesse está cada vez más distante.','2010-03-21'),(7,1,'Caballo sin nombre',47,8.7,3,'Walt encuentra problemas cuando regresa a su casa. Jesse lucha por su sobrevivencia.','2010-03-28'),(8,1,'I.F.T.',47,8.4,3,'Skyler toma una decisión que sorprende a Walt y Jesse. Las tensiones escalan.','2010-04-04'),(9,1,'Verde luz',45,8.5,3,'Walt pierde el control, poniendo en peligro todo lo que ha construido.','2010-04-11'),(10,1,'Más',47,8.8,3,'Jesse toma una decisión importante sobre su futuro mientras que Walt se consolida.','2010-04-18'),(11,1,'Atardecer',45,9.5,3,'Walt y Jesse se encuentran en una situación extrema y deben encontrar una salida rápida.','2010-04-25'),(12,2,'El desaparecido',50,9.0,1,'Cuando un niño desaparece, sus amigos encuentran una chica con poderes misteriosos.','2016-07-15'),(13,2,'La desaparición de Will Byers',47,9.0,1,'Después de que Will Byers desaparece misteriosamente, sus amigos comienzan una búsqueda que les lleva a encontrar a una chica con poderes extraños.','2016-07-15'),(14,2,'La loca de la calle Maple',55,8.9,1,'Lucas, Mike y Dustin intentan hablar con la chica que encontraron en el bosque. Mientras tanto, Hopper investiga la desaparición de Will.','2016-07-15'